#### Expected Behavior
When using raw pricing, volatility models should still be accurate after a split

#### Actual Behavior
Volatility models inaccurate after a split as they read the price jump as a discontinuity. 

#### Potential Solution
 - Bind volatility models to split events to be re-calculated on splits; 
 - Or force vol models to always use adjusted pricing. 

#### Reproducing the Problem
https://www.quantconnect.com/terminal/processCache/?request=embedded_backtest_b248a7d30a544c3527008eac184c9bd0.html
```csharp
namespace QuantConnect.Algorithm.CSharp
{
    public class BasicTemplateAlgorithm : QCAlgorithm
    {
    	Equity aapl;
        public override void Initialize() {
            SetStartDate(2014, 03, 01);
            SetEndDate(2014, 08, 30);
            SetCash(100000);
            aapl = AddEquity("AAPL", Resolution.Daily);
            aapl.SetDataNormalizationMode(DataNormalizationMode.Raw);
            aapl.SetVolatilityModel( new StandardDeviationOfReturnsVolatilityModel( 7 ) );
        }

        public override void OnData(Slice data) {
            if (!Portfolio.Invested) {
                SetHoldings("AAPL", 1);
                Debug("Purchased AAPL");
            }
            
            if (data.Splits.Keys.Count > 0) {
            	Debug("SPLIT Slice >> " + data.Splits["AAPL"].ToString());
            }
        }
        
        public override void OnEndOfDay() {
            Plot("Vol", "AAPL", aapl.VolatilityModel.Volatility);
        }
    }
}
```

